/* -----------------------------------------------------------------------
 * test_file_window.c
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Tony's display/UI subsystem (best-ui), with an AI coding assistant.
 * BJT2 Sound Modulating Toy — File List Window Unit Tests
 *
 * Covers file_window.c using the Unity test framework.
 * No hardware required — runs on any host PC via CMake.
 *
 * The windows below are what Jack sends: up to 16 names starting at list
 * position "first", out of "total" files. Name n of the whole list is
 * written "Fnnn.WAV", so a test can tell which list position it got.
 *
 * Test groups:
 *   Group A — Names: inside the window, outside it, the selected name
 *   Group B — When to ask Jack for another window (fw_wants)
 *   Group C — Loading a window, a changed list, a card that went
 *   Group D — NULL safety
 * ----------------------------------------------------------------------- */

#include "unity.h"
#include <stdio.h>
#include <string.h>
#include "file_window.h"

void setUp(void)   {}
void tearDown(void) {}

/* Shared instances reused across tests */
static fw_window_t w;
static char        names[FW_NAMES][FW_NAME_LEN];
static char        sel[FW_NAME_LEN];

/* Helper — load the window Jack would send for list positions
 * first .. first + count - 1 of a list of total files */
static void load(uint16_t first, uint8_t count, uint16_t total, uint16_t gen)
{
    memset(names, 0, sizeof(names));
    for (uint8_t i = 0U; i < count && i < FW_NAMES; i++) {
        snprintf(names[i], sizeof(names[i]), "F%03u.WAV", (unsigned)(first + i));
    }
    fw_init(&w);
    fw_apply(&w, first, count, total, gen);
    for (uint8_t i = 0U; i < count && i < FW_NAMES; i++) {
        fw_apply_name(&w, i, names[i]);
    }
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP A — Names
 * ═══════════════════════════════════════════════════════════════════════ */

void test_A01_a_name_inside_the_window_is_returned(void)
{
    load(32U, 16U, 120U, 1U);
    TEST_ASSERT_EQUAL_STRING("F032.WAV", fw_name(&w, 32U));     /* the first name */
    TEST_ASSERT_EQUAL_STRING("F040.WAV", fw_name(&w, 40U));
    TEST_ASSERT_EQUAL_STRING("F047.WAV", fw_name(&w, 47U));     /* the last name */
}

void test_A02_a_name_outside_the_window_is_null(void)
{
    load(32U, 16U, 120U, 1U);
    TEST_ASSERT_NULL(fw_name(&w, 31U));
    TEST_ASSERT_NULL(fw_name(&w, 48U));
    TEST_ASSERT_NULL(fw_name(&w, 0U));
    TEST_ASSERT_NULL(fw_name(&w, 65535U));

    fw_init(&w);                                    /* no window yet */
    TEST_ASSERT_NULL(fw_name(&w, 0U));

    load(0U, 0U, 0U, 1U);                           /* an empty card */
    TEST_ASSERT_NULL(fw_name(&w, 0U));
}

void test_A03_the_selected_name_follows_the_index_inside_the_window(void)
{
    load(0U, 16U, 40U, 1U);
    for (uint16_t i = 0U; i < 16U; i++) {
        char want[FW_NAME_LEN];
        snprintf(want, sizeof(want), "F%03u.WAV", (unsigned)i);
        fw_sel_name(&w, i, sel);
        TEST_ASSERT_EQUAL_STRING(want, sel);
    }
}

void test_A04_the_selected_name_is_empty_outside_the_window(void)
{
    load(0U, 16U, 40U, 1U);
    memset(sel, 'x', sizeof(sel));
    fw_sel_name(&w, 16U, sel);
    TEST_ASSERT_EQUAL_STRING("", sel);

    fw_init(&w);                                    /* no window at all */
    memset(sel, 'x', sizeof(sel));
    fw_sel_name(&w, 0U, sel);
    TEST_ASSERT_EQUAL_STRING("", sel);
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP B — fw_wants: ask for another window?
 * ═══════════════════════════════════════════════════════════════════════ */

void test_B01_it_wants_a_window_while_none_is_loaded(void)
{
    fw_init(&w);
    TEST_ASSERT_TRUE(fw_wants(&w, 0U));
    TEST_ASSERT_TRUE(fw_wants(&w, 300U));
}

void test_B02_it_wants_the_next_window_near_the_top_edge(void)
{
    /* Names 32..47 of 120: there are more above 32. The first FW_MARGIN
     * (3) names of the window want the window above. */
    load(32U, 16U, 120U, 1U);
    TEST_ASSERT_TRUE(fw_wants(&w, 32U));
    TEST_ASSERT_TRUE(fw_wants(&w, 34U));
    TEST_ASSERT_FALSE(fw_wants(&w, 35U));           /* 3 away from the edge: fine */
}

void test_B03_it_wants_the_next_window_near_the_bottom_edge(void)
{
    load(32U, 16U, 120U, 1U);
    TEST_ASSERT_TRUE(fw_wants(&w, 47U));
    TEST_ASSERT_TRUE(fw_wants(&w, 45U));
    TEST_ASSERT_FALSE(fw_wants(&w, 44U));
}

void test_B04_no_want_at_the_start_or_the_end_of_the_list(void)
{
    /* Nothing above list position 0 and nothing below the last file:
     * those edges are the list's own. */
    load(0U, 16U, 120U, 1U);
    TEST_ASSERT_FALSE(fw_wants(&w, 0U));
    TEST_ASSERT_FALSE(fw_wants(&w, 2U));
    TEST_ASSERT_TRUE(fw_wants(&w, 15U));            /* more below */

    load(104U, 16U, 120U, 1U);
    TEST_ASSERT_FALSE(fw_wants(&w, 119U));
    TEST_ASSERT_FALSE(fw_wants(&w, 117U));
    TEST_ASSERT_TRUE(fw_wants(&w, 104U));           /* more above */

    load(0U, 5U, 5U, 1U);                           /* the whole list fits */
    for (uint16_t i = 0U; i < 5U; i++) {
        TEST_ASSERT_FALSE(fw_wants(&w, i));
    }
}

void test_B05_it_wants_a_window_for_an_index_outside_it(void)
{
    load(32U, 16U, 120U, 1U);
    TEST_ASSERT_TRUE(fw_wants(&w, 31U));
    TEST_ASSERT_TRUE(fw_wants(&w, 48U));
    TEST_ASSERT_TRUE(fw_wants(&w, 0U));
    TEST_ASSERT_TRUE(fw_wants(&w, 119U));
}

void test_B06_an_empty_list_wants_nothing(void)
{
    load(0U, 0U, 0U, 1U);
    TEST_ASSERT_FALSE(fw_wants(&w, 0U));
    TEST_ASSERT_FALSE(fw_wants(&w, 5U));
}

void test_B07_a_centred_window_wants_nothing_until_the_margin(void)
{
    /* Jack centres the window: first = index - 8. Scrolling one name at a
     * time, the next window is wanted 3 names before the edge. */
    load(92U, 16U, 300U, 1U);                       /* centred on 100 */
    for (uint16_t i = 95U; i <= 104U; i++) {
        TEST_ASSERT_FALSE(fw_wants(&w, i));
    }
    TEST_ASSERT_TRUE(fw_wants(&w, 94U));
    TEST_ASSERT_TRUE(fw_wants(&w, 105U));
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP C — Loading a window, a changed list, a card that went
 * ═══════════════════════════════════════════════════════════════════════ */

void test_C01_apply_stores_the_raw_bytes(void)
{
    /* A PC can write code page 850 bytes (0x80 and up) into a name: they
     * stay as they are, so PLAY and Delete can name the file to Jack.
     * A name with no NUL in its 13 bytes is ended at the 13th. */
    memset(names, 0, sizeof(names));
    snprintf(names[0], sizeof(names[0]), "R%cSUM%c.WAV", (char)0x82, (char)0xE9);
    memset(names[1], 'A', FW_NAME_LEN);
    fw_init(&w);
    fw_apply(&w, 7U, 2U, 9U, 3U);
    fw_apply_name(&w, 0U, names[0]);
    fw_apply_name(&w, 1U, names[1]);

    TEST_ASSERT_EQUAL_HEX8(0x82, (uint8_t)fw_name(&w, 7U)[1]);
    TEST_ASSERT_EQUAL_HEX8(0xE9, (uint8_t)fw_name(&w, 7U)[5]);
    TEST_ASSERT_EQUAL_STRING(names[0], fw_name(&w, 7U));
    TEST_ASSERT_EQUAL_STRING("AAAAAAAAAAAA", fw_name(&w, 8U));    /* 12 letters + NUL */
    TEST_ASSERT_EQUAL_UINT16(7U, w.first);
    TEST_ASSERT_EQUAL_UINT8(2U, w.count);
    TEST_ASSERT_EQUAL_UINT16(9U, w.total);
    TEST_ASSERT_EQUAL_UINT16(3U, w.gen);
}

void test_C02_apply_keeps_at_most_16_names(void)
{
    fw_init(&w);
    fw_apply(&w, 0U, 200U, 300U, 1U);               /* a count no reply can have */
    TEST_ASSERT_EQUAL_UINT8(FW_NAMES, w.count);
    TEST_ASSERT_NULL(fw_name(&w, FW_NAMES));

    /* A name past the window's count is ignored: in a window of 2 names,
     * slot 2 (the first one past the count) and the last slot stay empty */
    fw_apply(&w, 0U, 2U, 40U, 1U);
    fw_apply_name(&w, 2U, "X.WAV");
    fw_apply_name(&w, FW_NAMES - 1U, "Y.WAV");
    TEST_ASSERT_EQUAL_STRING("", w.names[2]);
    TEST_ASSERT_EQUAL_STRING("", w.names[FW_NAMES - 1U]);
}

void test_C03_only_a_window_older_than_the_status_is_stale(void)
{
    load(0U, 16U, 40U, 7U);
    TEST_ASSERT_FALSE(fw_stale(&w, 7U));
    TEST_ASSERT_TRUE(fw_stale(&w, 8U));             /* Jack's list changed since */
    TEST_ASSERT_TRUE(fw_stale(&w, 20U));
    /* The window is NEWER than the status: the File screen's LIST_FILES
     * rescan moved list_gen on, and Jack's reply came before a status with
     * the new number. It is up to date, so the UI must not ask again (it
     * would ask for ever while no new status comes). */
    TEST_ASSERT_FALSE(fw_stale(&w, 6U));
    TEST_ASSERT_FALSE(fw_stale(&w, 0U));

    load(0U, 16U, 40U, 65535U);                     /* list_gen rolls over to 0 */
    TEST_ASSERT_TRUE(fw_stale(&w, 0U));             /* the status is one change ahead */
    load(0U, 16U, 40U, 0U);
    TEST_ASSERT_FALSE(fw_stale(&w, 65535U));        /* the window is one change ahead */

    fw_init(&w);                                    /* nothing loaded: nothing is stale */
    TEST_ASSERT_FALSE(fw_stale(&w, 7U));
}

void test_C04_apply_sets_ever(void)
{
    fw_init(&w);
    TEST_ASSERT_FALSE(fw_ever(&w));
    load(0U, 0U, 0U, 1U);                           /* even an empty card's window */
    TEST_ASSERT_TRUE(fw_ever(&w));
    TEST_ASSERT_TRUE(w.valid);
}

void test_C05_invalidate_forgets_the_window_and_ever(void)
{
    /* The card went (pulled, unmounted or on a PC): the next card starts
     * at its own last file. */
    load(0U, 16U, 40U, 1U);
    fw_invalidate(&w);
    TEST_ASSERT_FALSE(fw_ever(&w));
    TEST_ASSERT_FALSE(w.valid);
    TEST_ASSERT_NULL(fw_name(&w, 0U));
    TEST_ASSERT_TRUE(fw_wants(&w, 0U));
    TEST_ASSERT_FALSE(fw_stale(&w, 2U));
}

void test_C06_a_new_window_over_an_old_one_ends_every_name(void)
{
    /* tony_ui.c applies each reply over the window it already holds (no
     * fw_init first): a shorter name must not keep the end of the longer
     * name that was in its slot */
    load(0U, 16U, 40U, 1U);                         /* "F000.WAV" .. "F015.WAV" */
    fw_apply(&w, 0U, 2U, 2U, 2U);
    fw_apply_name(&w, 0U, "A.WAV");
    TEST_ASSERT_EQUAL_STRING("A.WAV", fw_name(&w, 0U));     /* not "A.WAVWAV" */
    TEST_ASSERT_NULL(fw_name(&w, 2U));
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP D — NULL safety
 * ═══════════════════════════════════════════════════════════════════════ */

void test_D01_null_is_safe(void)
{
    load(0U, 16U, 40U, 1U);
    fw_init(NULL);
    fw_invalidate(NULL);
    fw_apply(NULL, 0U, 1U, 1U, 1U);
    fw_apply_name(NULL, 0U, "A.WAV");
    fw_apply_name(&w, 0U, NULL);                    /* no name: nothing changes */
    TEST_ASSERT_EQUAL_STRING("F000.WAV", fw_name(&w, 0U));
    TEST_ASSERT_NULL(fw_name(NULL, 0U));
    memset(sel, 'x', sizeof(sel));                  /* so the "" below is fw_sel_name's */
    fw_sel_name(NULL, 0U, sel);
    TEST_ASSERT_EQUAL_STRING("", sel);
    fw_sel_name(&w, 0U, NULL);
    TEST_ASSERT_FALSE(fw_wants(NULL, 0U));
    TEST_ASSERT_FALSE(fw_stale(NULL, 0U));
    TEST_ASSERT_FALSE(fw_ever(NULL));
}

/* ═══════════════════════════════════════════════════════════════════════
 * TEST RUNNER
 * ═══════════════════════════════════════════════════════════════════════ */

int main(void)
{
    UNITY_BEGIN();

    /* Group A — Names */
    RUN_TEST(test_A01_a_name_inside_the_window_is_returned);
    RUN_TEST(test_A02_a_name_outside_the_window_is_null);
    RUN_TEST(test_A03_the_selected_name_follows_the_index_inside_the_window);
    RUN_TEST(test_A04_the_selected_name_is_empty_outside_the_window);

    /* Group B — fw_wants */
    RUN_TEST(test_B01_it_wants_a_window_while_none_is_loaded);
    RUN_TEST(test_B02_it_wants_the_next_window_near_the_top_edge);
    RUN_TEST(test_B03_it_wants_the_next_window_near_the_bottom_edge);
    RUN_TEST(test_B04_no_want_at_the_start_or_the_end_of_the_list);
    RUN_TEST(test_B05_it_wants_a_window_for_an_index_outside_it);
    RUN_TEST(test_B06_an_empty_list_wants_nothing);
    RUN_TEST(test_B07_a_centred_window_wants_nothing_until_the_margin);

    /* Group C — Loading, a changed list, a card that went */
    RUN_TEST(test_C01_apply_stores_the_raw_bytes);
    RUN_TEST(test_C02_apply_keeps_at_most_16_names);
    RUN_TEST(test_C03_only_a_window_older_than_the_status_is_stale);
    RUN_TEST(test_C04_apply_sets_ever);
    RUN_TEST(test_C05_invalidate_forgets_the_window_and_ever);
    RUN_TEST(test_C06_a_new_window_over_an_old_one_ends_every_name);

    /* Group D — NULL safety */
    RUN_TEST(test_D01_null_is_safe);

    return UNITY_END();
}
